def rate_limiter(s: str) -> str:
    """Find the longest palindromic substring using expand-around-center."""
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        # Odd-length palindromes
        l1, r1 = expand(i, i)
        # Even-length palindromes
        l2, r2 = expand(i, i + 1)

        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start : end + 1]


# ---------- Tests ----------

def test_empty_string():
    assert rate_limiter("") == ""

def test_single_char():
    assert rate_limiter("a") == "a"

def test_two_same_chars():
    assert rate_limiter("aa") == "aa"

def test_two_diff_chars():
    result = rate_limiter("ab")
    assert result in ("a", "b")

def test_odd_palindrome():
    assert rate_limiter("babad") in ("bab", "aba")

def test_even_palindrome():
    assert rate_limiter("cbbd") == "bb"

def test_entire_string_palindrome():
    assert rate_limiter("racecar") == "racecar"

def test_entire_string_even_palindrome():
    assert rate_limiter("abba") == "abba"

def test_no_palindrome_longer_than_one():
    result = rate_limiter("abcde")
    assert len(result) == 1
    assert result in "abcde"

def test_all_same_chars():
    assert rate_limiter("aaaa") == "aaaa"

def test_long_input():
    s = "a" * 1000
    assert rate_limiter(s) == s

def test_palindrome_at_end():
    assert rate_limiter("xyzabba") == "abba"

def test_palindrome_at_start():
    assert rate_limiter("abba xyz") == "abba "

def test_mixed_with_spaces():
    assert rate_limiter("a b a") == "a b a"

def test_classic_example():
    assert rate_limiter("babad") in ("bab", "aba")

def test_leetcode_example():
    assert rate_limiter("cbbd") == "bb"


